import { readdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const GENERATED_NOTICE =
  '<!-- Generated by scripts/update-generated-docs.mjs. Do not edit by hand. -->';
const EXCLUDED_DIRS = new Set(['.git', 'dist', 'node_modules']);
const EXCLUDED_PATHS = new Set(['.claude/settings.local.json']);
const LINE_BREAK_REGEX = /\r\n|\r|\n/;
const SOURCE_EXTENSIONS = new Set(['.ts', '.tsx']);
const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');

const COMMANDS = [
  {
    command: 'tenex new [name]',
    source: 'src/commands/new.ts',
    purpose: 'Create a new TanStack Start and Convex project.',
  },
  {
    command: 'tenex init [name]',
    source: 'src/commands/new.ts',
    purpose: 'Alias for `tenex new`.',
  },
  {
    command: 'tenex add <addon>',
    source: 'src/commands/add.ts',
    purpose: 'Enable a supported add-on in an existing Tenex project.',
  },
  {
    command: 'tenex doctor',
    source: 'src/commands/doctor.ts',
    purpose: 'Validate Tenex config and env requirements.',
  },
  {
    command: 'tenex dev',
    source: 'src/commands/dev.ts',
    purpose: 'Run the generated app and Convex dev process.',
  },
  {
    command: 'tenex deploy',
    source: 'src/commands/deploy.ts',
    purpose: 'Write deploy handoff output and run deploy validation.',
  },
];

const GENERATED_DOCS = [
  'docs/generated/cli-surface.md',
  'docs/generated/source-inventory.md',
];

const normalizePath = (path) => path.split(sep).join('/');

const hasSourceExtension = (path) =>
  [...SOURCE_EXTENSIONS].some((extension) => path.endsWith(extension));

const countLines = (contents) => {
  if (contents.length === 0) {
    return 0;
  }
  return (
    contents.split(LINE_BREAK_REGEX).length - (contents.endsWith('\n') ? 1 : 0)
  );
};

const readJsonFile = async (path) => {
  const contents = await readFile(path, 'utf8');
  return JSON.parse(contents);
};

const listFiles = async (dir, rootDir = dir) => {
  const entries = await readdir(dir, { withFileTypes: true });
  const sortedEntries = entries.toSorted((left, right) =>
    left.name.localeCompare(right.name)
  );
  const files = [];

  for (const entry of sortedEntries) {
    const absolutePath = join(dir, entry.name);
    const relativePath = normalizePath(relative(rootDir, absolutePath));

    if (entry.isDirectory()) {
      if (EXCLUDED_DIRS.has(entry.name)) {
        continue;
      }
      files.push(...(await listFiles(absolutePath, rootDir)));
      continue;
    }

    if (
      entry.isFile() &&
      !EXCLUDED_PATHS.has(relativePath) &&
      !GENERATED_DOCS.includes(relativePath)
    ) {
      files.push(relativePath);
    }
  }

  return files;
};

const formatTable = (headers, rows) => {
  const headerLine = `| ${headers.join(' | ')} |`;
  const dividerLine = `| ${headers.map(() => '---').join(' | ')} |`;
  const rowLines = rows.map((row) => `| ${row.join(' | ')} |`);
  return [headerLine, dividerLine, ...rowLines].join('\n');
};

const buildCliSurfaceDoc = (packageJson) => {
  const scripts = Object.entries(packageJson.scripts ?? {}).map(
    ([name, command]) => [`\`${name}\``, `\`${command}\``]
  );
  const dependencies = Object.entries(packageJson.dependencies ?? {}).map(
    ([name, version]) => [`\`${name}\``, `\`${version}\``]
  );
  const devDependencies = Object.entries(packageJson.devDependencies ?? {}).map(
    ([name, version]) => [`\`${name}\``, `\`${version}\``]
  );
  const commandRows = COMMANDS.map(({ command, purpose, source }) => [
    `\`${command}\``,
    purpose,
    `\`${source}\``,
  ]);

  return `${GENERATED_NOTICE}

# CLI Surface

Package: \`${packageJson.name}\`

Version: \`${packageJson.version}\`

Binary: \`tenex -> ${packageJson.bin?.tenex ?? 'dist/cli.js'}\`

## Commands

${formatTable(['Command', 'Purpose', 'Source'], commandRows)}

## Package Scripts

${formatTable(['Script', 'Command'], scripts)}

## Runtime Dependencies

${formatTable(['Package', 'Version'], dependencies)}

## Development Dependencies

${formatTable(['Package', 'Version'], devDependencies)}
`;
};

const buildSourceInventoryDoc = async (rootDir, files) => {
  const sourceFiles = files.filter((path) => path.startsWith('src/'));
  const docs = files.filter((path) => path.endsWith('.md'));
  const sourceRows = [];

  for (const path of sourceFiles.filter(hasSourceExtension)) {
    const contents = await readFile(join(rootDir, path), 'utf8');
    sourceRows.push([`\`${path}\``, String(countLines(contents))]);
  }

  const topLevelCounts = new Map();
  for (const path of files) {
    const [topLevel] = path.split('/');
    topLevelCounts.set(topLevel, (topLevelCounts.get(topLevel) ?? 0) + 1);
  }

  const directoryRows = [...topLevelCounts.entries()]
    .toSorted(([left], [right]) => left.localeCompare(right))
    .map(([directory, count]) => [`\`${directory}\``, String(count)]);

  return `${GENERATED_NOTICE}

# Source Inventory

Files outside ignored directories: ${files.length}

Markdown docs: ${docs.length}

Source files: ${sourceFiles.length}

## Top-Level Inventory

${formatTable(['Path', 'Files'], directoryRows)}

## Source Files

${formatTable(['Path', 'Lines'], sourceRows)}
`;
};

export const buildGeneratedDocs = async (rootDir = repoRoot) => {
  const packageJson = await readJsonFile(join(rootDir, 'package.json'));
  const files = await listFiles(rootDir);

  return new Map([
    ['docs/generated/cli-surface.md', buildCliSurfaceDoc(packageJson)],
    [
      'docs/generated/source-inventory.md',
      await buildSourceInventoryDoc(rootDir, files),
    ],
  ]);
};

export const writeGeneratedDocs = async (rootDir = repoRoot) => {
  const docs = await buildGeneratedDocs(rootDir);

  for (const [path, contents] of docs) {
    await writeFile(join(rootDir, path), contents, 'utf8');
  }
};

const main = async () => {
  await writeGeneratedDocs();
  console.log('Generated docs updated.');
};

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    const message = error instanceof Error ? error.message : String(error);
    console.error(message);
    process.exitCode = 1;
  });
}
